-- Reference migration for the tenant registry (`TomSqlTenantRegistry`).
--
-- Creates `tom_tenant`, one row per tenant of the deployment: the durable list
-- `TomTenancy` reads at install, writes every lifecycle change to, and every
-- node refreshes its routing from. This file is the canonical DDL and is kept
-- in sync with `tenantTable()` in
-- `lib/src/tomserver/tenancy/tenant_registry_sql.dart`;
-- `test/framework_schema_test.dart` replays this chain and compares the schema
-- it builds against the descriptor, so the two cannot drift apart.
--
-- Apply this file in the system schema — the base schema of the registry's
-- data source, never a tenant's — when the application's database user is not
-- permitted to run DDL, and configure the registry with `createSchema: false`.
--
-- Notes on the shape:
--
--  * `status` is one of provisioning, migrating, active, suspended,
--    migration-failed, removed.
--  * `datasources` and `migrated` are JSON: a tenant's data sources (never a
--    literal password) and the migration version applied per
--    `<datasource>/<schema>`.
CREATE TABLE IF NOT EXISTS tom_tenant (
  id VARCHAR(32) NOT NULL,
  type VARCHAR(64) NOT NULL,
  name VARCHAR(191) NULL,
  isolation VARCHAR(16) NULL,
  schema_name VARCHAR(64) NULL,
  datasources TEXT NULL,
  status VARCHAR(32) NOT NULL,
  status_detail TEXT NULL,
  migrated TEXT NULL,
  created_at TIMESTAMP(6) NOT NULL,
  updated_at TIMESTAMP(6) NOT NULL,
  PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_tom_tenant_status ON tom_tenant (status);
